<?php
namespace App\Http\Controllers;
use App\Models\{Faq,PublicPage,Activity};
use App\Services\{PageRegistry,ArticleContent};
use App\Http\Requests\SaveFaqRequest;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class FaqController extends Controller {
 public function index(Request $r){$q=Faq::withCount('pages');if($r->status==='archived')$q->onlyTrashed();elseif(in_array($r->status,['draft','published'],true))$q->where('status',$r->status);if($r->filled('q'))$q->where('question','like','%'.mb_substr($r->q,0,100).'%');if($r->filled('page_id'))$q->whereHas('pages',fn($q)=>$q->where('public_pages.id',$r->page_id));if($r->filled('category'))$q->where('category',$r->category);return view('centre.index',['kind'=>'faqs','title'=>'FAQs','items'=>$q->latest()->paginate(15)->withQueryString(),'destinations'=>PublicPage::orderBy('kind')->orderBy('title')->get()]);}
 public function create(){return view('centre.faq-form',['faq'=>new Faq(['status'=>'draft']),'pages'=>PublicPage::orderBy('kind')->orderBy('title')->get()]);}
 public function edit(Faq $faq){return view('centre.faq-form',['faq'=>$faq->load('pages'),'pages'=>PublicPage::orderBy('kind')->orderBy('title')->get()]);}
 public function show(Faq $faq){return view('centre.faq-show',['faq'=>$faq->load('pages')]);}
 public function store(SaveFaqRequest $r){return $this->save($r,new Faq);}
 public function update(SaveFaqRequest $r,Faq $faq){return $this->save($r,$faq);}
 private function save(SaveFaqRequest $r,Faq $faq){$d=$r->validated();$ids=$d['pages']??[];$orders=$d['orders']??[];unset($d['pages'],$d['orders']);$d['answer_html']=app(ArticleContent::class)->sanitize($d['answer_html']??'');$d['question_key']=app(PageRegistry::class)->questionKey($d['question']);if(Faq::withTrashed()->where('question_key',$d['question_key'])->when($faq->exists,fn($q)=>$q->where('id','!=',$faq->id))->exists())throw ValidationException::withMessages(['question'=>'This question already exists. Assign that FAQ to another page instead of duplicating it.']);if($d['status']==='published'&&!trim(strip_tags($d['answer_html'])))throw ValidationException::withMessages(['answer_html'=>'Add an answer before publishing.']);if(!empty($d['schema_page_id'])&&!in_array((int)$d['schema_page_id'],array_map('intval',$ids),true))throw ValidationException::withMessages(['schema_page_id'=>'The canonical schema destination must be one of the assigned pages.']);$d['updated_by']=$r->user()->id;DB::transaction(function()use($faq,$d,$ids,$orders){$faq->fill($d)->save();$faq->pages()->sync(collect($ids)->mapWithKeys(fn($id)=>[$id=>['display_order'=>(int)($orders[$id]??0)]])->all());});Activity::record('FAQ saved','FAQ #'.$faq->id);return redirect()->route('faqs.edit',$faq)->with('success','FAQ and page assignments saved.');}
 public function destroy(Faq $faq){$faq->delete();return redirect()->route('faqs.index')->with('success','FAQ archived. Assignments are preserved for recovery.');}
 public function restore(int $faq){$f=Faq::onlyTrashed()->findOrFail($faq);$f->status='draft';$f->restore();$f->save();return back()->with('success','FAQ restored as draft.');}
 public function generate(Request $r,PageRegistry $registry){$d=$r->validate(['page_id'=>['required','exists:public_pages,id']]);$page=PublicPage::findOrFail($d['page_id']);return view('centre.faq-suggestions',['page'=>$page,'suggestions'=>$registry->suggestions($page)]);}
 public function acceptDrafts(Request $r){$d=$r->validate(['page_id'=>['required','exists:public_pages,id'],'suggestions'=>['required','array','max:8'],'selected'=>['required','array','min:1','max:8'],'selected.*'=>['integer','min:0','max:7'],'suggestions.*.question'=>['required','string','max:500'],'suggestions.*.answer'=>['nullable','string','max:5000']]);$count=0;DB::transaction(function()use($r,$d,&$count){foreach(array_unique($d['selected']) as $index){if(!isset($d['suggestions'][$index]))continue;$s=$d['suggestions'][$index];$key=app(PageRegistry::class)->questionKey($s['question']);if(Faq::withTrashed()->where('question_key',$key)->exists())continue;$f=Faq::create(['question'=>$s['question'],'question_key'=>$key,'answer_html'=>app(ArticleContent::class)->sanitize('<p>'.e($s['answer']??'').'</p>'),'status'=>'draft','editorial_notes'=>'Template-based draft helper; review factual accuracy before publishing.','updated_by'=>$r->user()->id]);$f->pages()->attach($d['page_id'],['display_order'=>0]);$count++;}});Activity::record('Template FAQ drafts created','Count '.$count);return redirect()->route('faqs.index')->with('success',$count.' draft FAQs created. None were published.');}
}
